import json

_CHECKS = {
    'string': lambda v: isinstance(v, str),
    'integer': lambda v: isinstance(v, int) and not isinstance(v, bool),
    'number': lambda v: isinstance(v, (int, float)) and not isinstance(v, bool),
    'boolean': lambda v: isinstance(v, bool),
    'array': lambda v: isinstance(v, list),
}


def _strip_fence(text):
    text = text.strip()
    if text.startswith('```'):
        first_nl = text.find('\n')
        text = text[first_nl + 1:] if first_nl != -1 else ''
        if text.rstrip().endswith('```'):
            text = text.rstrip()[:-3]
    return text.strip()


def validate_output(raw, schema):
    try:
        data = json.loads(_strip_fence(raw))
    except json.JSONDecodeError:
        return ['invalid JSON']
    if not isinstance(data, dict):
        return ['root: expected object']
    errors = []
    for field, rule in schema.items():
        if field not in data:
            if rule.get('required', True):
                errors.append(f'{field}: missing')
            continue
        value = data[field]
        if not _CHECKS[rule['type']](value):
            errors.append(f"{field}: expected {rule['type']}")
        elif 'enum' in rule and value not in rule['enum']:
            errors.append(f"{field}: not one of {rule['enum']!r}")
    for key in sorted(set(data) - set(schema)):
        errors.append(f'{key}: unexpected field')
    return errors
